var doc = Document;
// Goal: dimension the clear distance between two parallel walls on the floor plan of their level.

// 1. The level, and the plan view that LOOKS AT that level. Annotations go into a view; a
//    level-scoped plan is found by ViewPlan.GenLevel, skipping view templates. (The default
//    template has a plan per level; a level created by script has NO plan until ViewPlan.Create
//    makes one -- see levels-grids-and-plan-views.)
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
Autodesk.Revit.DB.ViewPlan plan = null;
foreach (Autodesk.Revit.DB.ViewPlan v in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewPlan))) {
  if (!v.IsTemplate && v.GenLevel != null && v.GenLevel.Id == level.Id) { plan = v; break; }
}
if (plan == null) { throw new System.Exception("no floor plan for level " + level.Name + "; create one with ViewPlan.Create first"); }

return Connector.WithTransaction(doc, () => {
  // 2. Two parallel walls 20 ft apart (setup; a real task starts with walls that exist).
  var wallA = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(200, 0, 0), new Autodesk.Revit.DB.XYZ(220, 0, 0)), level.Id, false);
  var wallB = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(200, 20, 0), new Autodesk.Revit.DB.XYZ(220, 20, 0)), level.Id, false);
  doc.Regenerate();

  // 3. References. A dimension needs geometry references, not elements: HostObjectUtils.GetSideFaces
  //    gives a wall's face references without opening its geometry. The dimension measures
  //    FACE to FACE, so the reading depends on which faces are referenced, not on the 20 ft
  //    between the location lines: "Interior"/"Exterior" is relative to each wall's own
  //    direction, so two walls drawn the same way put their Interior faces on the same side
  //    (reading close to the centreline spacing), while opposite directions or mixed sides shift
  //    it by up to a wall thickness (Wall.Width). Do not assert an exact number.
  var refsA = Autodesk.Revit.DB.HostObjectUtils.GetSideFaces(wallA, Autodesk.Revit.DB.ShellLayerType.Interior);
  var refsB = Autodesk.Revit.DB.HostObjectUtils.GetSideFaces(wallB, Autodesk.Revit.DB.ShellLayerType.Interior);
  var refs = new Autodesk.Revit.DB.ReferenceArray();
  refs.Append(refsA[0]);
  refs.Append(refsB[0]);

  // 4. The dimension line sets where the dimension is drawn; it must cross the references.
  var dimLine = Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(210, 0, 0), new Autodesk.Revit.DB.XYZ(210, 20, 0));
  var dim = doc.Create.NewDimension(plan, dimLine, refs);

  // 5. Verify: Dimension.Value is in internal units (feet). For 20 ft location-line spacing a
  //    correct face pairing reads between 19 and 20.9 ft (centreline spacing +/- up to one
  //    Wall.Width); anything over that means the wrong faces (e.g. exterior to exterior).
  double centreline = 20.0;
  double value = dim.Value ?? 0;
  return new { dimensionId = dim.Id.Value, viewName = plan.Name, valueFeet = value, centrelineSpacingFeet = centreline, wallWidthFeet = wallA.Width, withinExpectedBand = value >= 19.0 && value <= 20.9 };
});
